SELECT 'audit' AS section, status AS item, COUNT(*) AS n, MAX(updated_at) AS latest_ksa FROM local_reconciliation_audit GROUP BY status UNION ALL SELECT 'signals_1m', CONCAT(symbol, ':', TIMESTAMPDIFF(MINUTE, MAX(generated_at), NOW()), 'm'), COUNT(*), MAX(generated_at) FROM trade_signal WHERE interval_code='1m' AND generated_at >= NOW() - INTERVAL 4 HOUR GROUP BY symbol ORDER BY section,item